assert sum(len(c['steps']) for c in insertion['cases'])==384 and sum(len(c['duplicate_steps']) for c in insertion['cases'])==36 and sum(len(c['removal_steps']) for c in insertion['cases'])==384
registration_path=root/'data/4.20/audio_announcer_actor_registration_contract.json';registration=load(registration_path);assert registration['passed'] and len(registration['cases'])==64
now=datetime.datetime.now(datetime.timezone.utc)
